      'ml':
          '\"വരാനിരിക്കുന്ന ക്ലാസുകളെക്കുറിച്ചും പരിശീലന ഷെഡ്യൂളുകളെക്കുറിച്ചും ഉപയോക്താക്കളെ അറിയിക്കുന്ന അറിയിപ്പുകളും ഓർമ്മപ്പെടുത്തലുകളും അവർക്ക് ഇമെയിൽ, SMS അല്ലെങ്കിൽ ആപ്ലിക്കേഷനിലെ അറിയിപ്പുകൾ വഴി അയയ്ക്കും.\"',
      'or':
          'ଉପଭୋକ୍ତାମାନଙ୍କୁ ଆଗାମୀ ଶ୍ରେଣୀ ଏବଂ ତାଲିମ କାର୍ଯ୍ୟସୂଚୀ ବିଷୟରେ ଅବଗତ କରୁଥିବା ବିଜ୍ଞପ୍ତି ଏବଂ ସ୍ମାରକପତ୍ର ସେମାନଙ୍କୁ ଇମେଲ, SMS କିମ୍ବା ଆବେଦନ ମଧ୍ୟରେ ବିଜ୍ଞପ୍ତି ମାଧ୍ୟମରେ ପଠାଯିବ ବୋଲି ସେ କହିଛନ୍ତି।',
      'ta':
          '\"வரவிருக்கும் வகுப்புகள் மற்றும் பயிற்சி அட்டவணைகள் குறித்து பயனர்களுக்குத் தெரிவிக்கும் அறிவிப்புகள் மற்றும் நினைவூட்டல்கள் விண்ணப்பத்தில் உள்ள மின்னஞ்சல், SMS அல்லது அறிவிப்புகள் மூலம் அவர்களுக்கு அனுப்பப்படும்.\"',
      'te':
          '\"రాబోయే తరగతులు మరియు శిక్షణ షెడ్యూల్‌ల గురించి వినియోగదారులకు తెలియజేసే నోటిఫికేషన్‌లు మరియు రిమైండర్‌లు అప్లికేషన్‌లోని ఇమెయిల్, SMS లేదా నోటిఫికేషన్‌ల ద్వారా వారికి పంపబడతాయి.\"',
      'ur':
          '\"صارفین کو آنے والی کلاسوں اور تربیتی نظام الاوقات کے بارے میں مطلع کرنے والی اطلاعات اور یاد دہانیاں انہیں ای میل، ایس ایم ایس یا ایپلی کیشن کے اندر اطلاعات کے ذریعے بھیجی جائیں گی۔\"',
