          'उपयोगकर्ता कक्षा प्रकार, स्थान, समय और प्रशिक्षक के आधार पर फ़िल्टर करके फिटनेस कक्षाओं की हमारी व्यापक सूची को ब्राउज़ कर सकता है। प्रत्येक कक्षा में कार्यक्रम, प्रशिक्षकों, समय, उपलब्धता और दरों का विस्तृत विवरण होगा।',
      'ml':
          'ക്ലാസ് തരം, ലൊക്കേഷൻ, സമയം, ഇൻസ്ട്രക്ടർ എന്നിവയെ അടിസ്ഥാനമാക്കി ഫിൽട്ടർ ചെയ്യുന്നതിലൂടെ ഉപയോക്താവിന് ഞങ്ങളുടെ ഫിറ്റ്നസ് ക്ലാസുകളുടെ വിപുലമായ കാറ്റലോഗിലൂടെ ബ്രൗസ് ചെയ്യാൻ കഴിയും. ഓരോ ക്ലാസിലും പ്രോഗ്രാമിന്റെ വിശദമായ വിവരണങ്ങൾ, ഇൻസ്ട്രക്ടർമാർ, സമയം, ലഭ്യത, നിരക്കുകൾ എന്നിവ ഉണ്ടായിരിക്കും.',
      'or':
          'ଉପଭୋକ୍ତା ଶ୍ରେଣୀ ପ୍ରକାର, ଅବସ୍ଥାନ, ସମୟ, ଏବଂ ନିର୍ଦେଶକ ଉପରେ ଆଧାର କରି ଫିଲ୍ଟର କରି ଆମର ଫିଟନେସ୍ ଶ୍ରେଣୀର ବିସ୍ତୃତ କାଟାଲଗ୍ ମାଧ୍ୟମରେ ବ୍ରାଉଜ୍ କରିପାରିବେ | ପ୍ରତ୍ୟେକ ଶ୍ରେଣୀରେ ପ୍ରୋଗ୍ରାମ, ନିର୍ଦେଶକ, ସମୟ, ଉପଲବ୍ଧତା ଏବଂ ହାରର ବିସ୍ତୃତ ବର୍ଣ୍ଣନା ରହିବ |',
      'ta':
          'வகுப்பின் வகை, இருப்பிடம், நேரம் மற்றும் பயிற்றுவிப்பாளர் ஆகியவற்றின் அடிப்படையில் வடிகட்டுவதன் மூலம் உடற்பயிற்சி வகுப்புகளின் விரிவான பட்டியலைப் பயனர் உலாவலாம். ஒவ்வொரு வகுப்பிலும் நிரல், பயிற்றுனர்கள், நேரம், கிடைக்கும் தன்மை மற்றும் கட்டணங்கள் பற்றிய விரிவான விளக்கங்கள் இருக்கும்.',
      'te':
          'తరగతి రకం, స్థానం, సమయం మరియు బోధకుడి ఆధారంగా ఫిల్టర్ చేయడం ద్వారా వినియోగదారు మా విస్తృతమైన ఫిట్‌నెస్ తరగతుల కేటలాగ్ ద్వారా బ్రౌజ్ చేయవచ్చు. ప్రతి తరగతికి ప్రోగ్రామ్, బోధకులు, సమయాలు, లభ్యత మరియు ధరల వివరణాత్మక వివరణలు ఉంటాయి.',
      'ur':
          'صارف کلاس کی قسم، مقام، وقت، اور انسٹرکٹر کی بنیاد پر فلٹرنگ کرکے فٹنس کلاسز کے ہمارے وسیع کیٹلاگ کو براؤز کر سکتا ہے۔ ہر کلاس میں پروگرام، انسٹرکٹرز، اوقات، دستیابی اور نرخوں کی تفصیلی وضاحت ہوگی۔',
    },
